import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"ADR-006: Two outputs (master + size-targeted share) and the bitrate formula","description":"","frontmatter":{},"headers":[],"relativePath":"adr/006-master-and-share-outputs.md","filePath":"adr/006-master-and-share-outputs.md"}'),o={name:"adr/006-master-and-share-outputs.md"};function i(n,e,d,u,l,c){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-006-two-outputs-master-size-targeted-share-and-the-bitrate-formula" tabindex="-1">ADR-006: Two outputs (master + size-targeted share) and the bitrate formula <a class="header-anchor" href="#adr-006-two-outputs-master-size-targeted-share-and-the-bitrate-formula" aria-label="Permalink to &quot;ADR-006: Two outputs (master + size-targeted share) and the bitrate formula&quot;">​</a></h1><ul><li>Status: accepted · Date: 2026-10-15</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ul><li><strong>Master:</strong> H.264 High, CRF 18, <code>slow</code>, yuv420p, 30 fps CFR, AAC 192 kb/s 48 kHz, faststart.</li><li><strong>Share:</strong> two-pass at <code>video_kbps = floor((MB × 8192 × 0.97) / duration) − 128</code>, maxrate 1.5×, bufsize 3×, AAC 128 kb/s, capped at 8 Mb/s (higher buys nothing visible at 1080×1920@30). If the result exceeds the cap it is re-encoded once at 90 %.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>Platforms re-encode uploads anyway; a predictable, compliant share file avoids rejection and keeps upload fast, while the master stays archival quality. Every output is verified with ffprobe (NFR-13).</p>',6)])])}const m=a(o,[["render",i]]);export{p as __pageData,m as default};
